class Solution(object):
    def firstUniqChar(self, s):
        """
        :type s: str
        :rtype: int
        """
        pos_info = {}
        for i, c in enumerate(s):
            if c not in pos_info:
                pos_info[c] = i
            else:
                pos_info[c] = -1
        ans = len(s)
        for pos in pos_info.values():
            if pos != -1 and pos < ans:
                ans = pos
        return -1 if ans == len(s) else ans
